</div></div></div></div><script>document.querySelectorAll('[data-role]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-role]').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.getElementById('role').value=b.dataset.role;document.getElementById('userLabel').textContent=b.dataset.role==='mahasiswa'?'NPM':(b.dataset.role==='dosen'?'NIDN':'Username');document.getElementById('username').placeholder='Masukkan '+(b.dataset.role==='mahasiswa'?'NPM':(b.dataset.role==='dosen'?'NIDN':'username'))+' Anda'});</script><?php require __DIR__.'/partials/footer.php'; ?>
